sys_script_client.script:
function onLoad() {

    if (g_scratchpad.blkTskRelated == 'Checker' && g_form.getValue('state') == '2' && g_form.getValue('outcome') == 'Amend Trade') {
        // g_form.addInfoMessage('loop1');
        if (typeof g_scratchpad != 'undefined' &&
            (g_scratchpad.recreatedCheckerbulk === true || g_scratchpad.recreatedCheckerbulk === 'true')) {
            g_form.setDisplay('decision', true);
            //  g_form.addInfoMessage('loop2');
        } else {
            g_form.setDisplay('decision', false);
        }
    } else {
        g_form.setDisplay('decision', false);
    }
}
